local file = os.tmpname()
os.remove(file)
local function notes(args)
    local pipe = io.popen("NOTES_FILE=" .. file .. " luajit notes.lua " .. args .. "; echo \"exit $?\"")
    local out = pipe:read("*a")
    pipe:close()
    return out
end
assert(notes("add buy milk '#home'"):find("added 1", 1, true), "first add")
assert(notes("add fix the '#bike' chain"):find("added 2", 1, true), "second add")
local listed = notes("list")
assert(listed:find("buy milk", 1, true) and listed:find("fix the", 1, true), "list shows both")
assert(listed:find("buy milk", 1, true) < listed:find("fix the", 1, true), "in order")
local tagged = notes("list '#bike'")
assert(tagged:find("fix the", 1, true) and not tagged:find("buy milk", 1, true), "list by tag")
assert(notes("find MILK"):find("buy milk", 1, true), "find")
assert(notes("frobnicate"):find("exit 1", 1, true), "usage exits 1")
os.remove(file)
print("301 ok")
